import{_ as e,o as t,c as i,ag as l}from"./chunks/framework.BcZEdlUI.js";const p=JSON.parse('{"title":"疑难排查","description":"SceneFab 常见问题与解决方案。","frontmatter":{"title":"疑难排查","description":"SceneFab 常见问题与解决方案。"},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md","lastUpdated":1780149682000}'),o={name:"guide/troubleshooting.md"};function r(n,a,s,d,h,c){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="疑难排查" tabindex="-1">疑难排查 <a class="header-anchor" href="#疑难排查" aria-label="Permalink to &quot;疑难排查&quot;">​</a></h1><h2 id="启动问题" tabindex="-1">启动问题 <a class="header-anchor" href="#启动问题" aria-label="Permalink to &quot;启动问题&quot;">​</a></h2><h3 id="no-module-named-scenefab" tabindex="-1">&quot;No module named &#39;scenefab&#39;&quot; <a class="header-anchor" href="#no-module-named-scenefab" aria-label="Permalink to &quot;&quot;No module named &#39;scenefab&#39;&quot;&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scenefab</span></span></code></pre></div><h3 id="ffmpeg-not-found" tabindex="-1">&quot;ffmpeg not found&quot; <a class="header-anchor" href="#ffmpeg-not-found" aria-label="Permalink to &quot;&quot;ffmpeg not found&quot;&quot;">​</a></h3><table tabindex="0"><thead><tr><th>系统</th><th>解决方法</th></tr></thead><tbody><tr><td>Windows</td><td>下载 <a href="https://ffmpeg.org/download.html" target="_blank" rel="noreferrer">FFmpeg</a>，添加到 PATH</td></tr><tr><td>macOS</td><td><code>brew install ffmpeg</code></td></tr><tr><td>Linux</td><td><code>sudo apt install ffmpeg</code></td></tr></tbody></table><hr><h2 id="ai-服务问题" tabindex="-1">AI 服务问题 <a class="header-anchor" href="#ai-服务问题" aria-label="Permalink to &quot;AI 服务问题&quot;">​</a></h2><h3 id="deepseek-api-key-无效-401" tabindex="-1">DeepSeek API Key 无效（401） <a class="header-anchor" href="#deepseek-api-key-无效-401" aria-label="Permalink to &quot;DeepSeek API Key 无效（401）&quot;">​</a></h3><ol><li>确认 Key 格式正确（<code>sk-</code> 开头）</li><li>检查 Key 是否已过期或被删除</li><li>确认 Key 已正确填入设置页</li></ol><h3 id="api-调用报-429-rate-limit" tabindex="-1">API 调用报 429 Rate Limit <a class="header-anchor" href="#api-调用报-429-rate-limit" aria-label="Permalink to &quot;API 调用报 429 Rate Limit&quot;">​</a></h3><ul><li>降低并发请求数</li><li>开启上下文缓存降低 token 消耗</li><li>升级 DeepSeek 账号套餐</li></ul><h3 id="qwen-vl-分析失败" tabindex="-1">Qwen VL 分析失败 <a class="header-anchor" href="#qwen-vl-分析失败" aria-label="Permalink to &quot;Qwen VL 分析失败&quot;">​</a></h3><ul><li>检查 Qwen API Key 余额</li><li>确认视频格式受支持（mp4/mov/avi/webm）</li></ul><hr><h2 id="视频处理问题" tabindex="-1">视频处理问题 <a class="header-anchor" href="#视频处理问题" aria-label="Permalink to &quot;视频处理问题&quot;">​</a></h2><h3 id="视频导入后无响应" tabindex="-1">视频导入后无响应 <a class="header-anchor" href="#视频导入后无响应" aria-label="Permalink to &quot;视频导入后无响应&quot;">​</a></h3><ul><li>确认视频文件未损坏</li><li>尝试重新编码：<code>ffmpeg -i input.mp4 -c:v libx264 output.mp4</code></li><li>检查磁盘空间是否充足</li></ul><h3 id="分析时间过长" tabindex="-1">分析时间过长 <a class="header-anchor" href="#分析时间过长" aria-label="Permalink to &quot;分析时间过长&quot;">​</a></h3><ul><li>减少视频数量</li><li>在设置中降低分析帧率（抽帧间隔改为 2 秒）</li><li>确认网络连接正常（API 调用需联网）</li></ul><hr><h2 id="导出问题" tabindex="-1">导出问题 <a class="header-anchor" href="#导出问题" aria-label="Permalink to &quot;导出问题&quot;">​</a></h2><h3 id="导出进度卡在-0" tabindex="-1">导出进度卡在 0% <a class="header-anchor" href="#导出进度卡在-0" aria-label="Permalink to &quot;导出进度卡在 0%&quot;">​</a></h3><ul><li>检查临时目录空间</li><li>确认输出目录有写入权限</li></ul><h3 id="导出文件无声" tabindex="-1">导出文件无声 <a class="header-anchor" href="#导出文件无声" aria-label="Permalink to &quot;导出文件无声&quot;">​</a></h3><ul><li>确认原视频包含音频轨道</li><li>尝试切换导出编码器</li></ul><hr><h2 id="界面问题" tabindex="-1">界面问题 <a class="header-anchor" href="#界面问题" aria-label="Permalink to &quot;界面问题&quot;">​</a></h2><h3 id="窗口显示异常" tabindex="-1">窗口显示异常 <a class="header-anchor" href="#窗口显示异常" aria-label="Permalink to &quot;窗口显示异常&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SceneFab &gt; 设置 &gt; 界面 &gt; 重置窗口布局</span></span></code></pre></div><h3 id="侧边栏点击无反应" tabindex="-1">侧边栏点击无反应 <a class="header-anchor" href="#侧边栏点击无反应" aria-label="Permalink to &quot;侧边栏点击无反应&quot;">​</a></h3><ul><li>升级到最新版本</li><li>删除配置文件：<code>~/.scenefab/config.json</code></li></ul><div class="tip custom-block"><p class="custom-block-title">💡 提示</p><p>找不到解决方案？ → <a href="https://github.com/Agions/scene-fab/issues" target="_blank" rel="noreferrer">提交 Issue</a></p></div>',33)])])}const b=e(o,[["render",r]]);export{p as __pageData,b as default};
